            kev.fflags = ((((((std.c.NOTE.WRITE | std.c.NOTE.DELETE) | std.c.NOTE.RENAME) | std.c.NOTE.EXTEND) | std.c.NOTE.ATTRIB) | std.c.NOTE.LINK) | std.c.NOTE.REVOKE);
            kev.udata = gen;
