            }
            _ = bun.handleOom(plat.entries.put(bun.default_allocator, @intCast(fd.native()), .{ .watcher = watcher, .fd = fd, .subpath = bun.handleOom(bun.default_allocator.dupeZ(u8, subpath)), .gen = gen, .is_file = is_file }));
            _ = bun.handleOom(watcher.platform.fds.append(bun.default_allocator, @intCast(fd.native())));
            return .success;
    }

pub fn removeWatch(manager: *PathWatcherManager, watcher: *PathWatcher) void {
            const plat = (&manager.platform);
