    }

pub fn threadMain(manager: *PathWatcherManager) void {
            _ = Output.Source.configureNamedThread("fs.watch");
            const plat = (&manager.platform);
            var events: [128]std.c.Kevent = undefined;
            _ = &events;
            while (plat.running.load(.acquire)) {
                const count = bun.sys.syscall.kevent(plat.kq.native(), (&events), 0, (&events), events.len, null);
                if ((count <= 0)) {
                    continue;
                }
                _ = (if (comptime @typeInfo(@TypeOf(manager.mutex)) == .pointer) (manager.mutex) else &(manager.mutex)).lock();
                var touched: std.AutoArrayHashMapUnmanaged(*PathWatcher,void) = .{};
                _ = &touched;
                defer {
                _ = touched.deinit(bun.default_allocator);
                }
                for (cp_iter_slice(events[0..@intCast(count)])) |kev| {
                    _ = &kev;
                    const entry_opt = plat.entries.getPtr(@intCast(kev.ident));
                    if ((entry_opt == null)) {
                        continue;
                    }
                    const entry = entry_opt.?;
                    if ((entry.gen != kev.udata)) {
                        continue;
                    }
                    const watcher = entry.watcher;
                    const event_type: PathWatcher.EventType = (if ((kev.fflags & ((((std.c.NOTE.DELETE | std.c.NOTE.RENAME) | std.c.NOTE.REVOKE) | std.c.NOTE.LINK) != 0))) .rename else .change);
                    const rel: []const u8 = (if ((entry.is_file and (entry.subpath.len == 0))) bun.path.basename(watcher.path) else entry.subpath);
                    _ = watcher.emit(event_type, rel, entry.is_file);
                    _ = bun.handleOom(touched.getOrPut(bun.default_allocator, watcher));
                }
                for (cp_iter_slice(touched.keys())) |w| {
                    _ = &w;
                    _ = w.flush();
                }
                _ = (if (comptime @typeInfo(@TypeOf(manager.mutex)) == .pointer) (manager.mutex) else &(manager.mutex)).unlock();
            }
    }
