pub fn watch(vm: *VirtualMachine, path: [:0]const u8, recursive: bool, comptime callback: PathWatcher.Callback, comptime updateEnd: PathWatcher.UpdateEndCallback, ctx: *anyopaque) bun.sys.Maybe(*PathWatcher) {
        _ = (comptime bun.assert((callback == onPathUpdateFn)));
        _ = (comptime bun.assert((updateEnd == onUpdateEndFn)));
        _ = &vm;
        const manager = (switch (PathWatcherManager.get()) {
.err => |e| {
return .{ .err = e };
},
.result => |m| m,
});
        var resolve_buf = bun.path_buffer_pool.get();
        _ = &resolve_buf;
        defer {
        _ = bun.path_buffer_pool.put(resolve_buf);
        }
        var is_file = false;
        _ = &is_file;
        var probe_fd: bun.FD = undefined;
        _ = &probe_fd;
        switch (bun.sys.open(path, ((bun.O.PATH | bun.O.DIRECTORY) | bun.O.CLOEXEC), 0)) {
.result => |f| {
probe_fd = f;
},
.err => |e| {
if ((e.getErrno() == .NOTDIR)) {
            is_file = true;
            switch (bun.sys.open(path, (bun.O.PATH | bun.O.CLOEXEC), 0)) {
.result => |f| {
probe_fd = f;
},
.err => |e2| {
return .{ .err = e2.withoutPath() };
},
}
        } else {
            return .{ .err = e.withoutPath() };
        }
},
}
        defer {
        _ = probe_fd.close();
        }
        const resolved: [:0]const u8 = (switch (bun.sys.getFdPath(probe_fd, resolve_buf)) {
.err => path,
.result => |r| brk: {
        resolve_buf[cp_cast_int(usize, r.len)] = 0;
        break :brk resolve_buf[0..r.len :0];
},
});
        const key_buf = bun.path_buffer_pool.get();
        defer {
        _ = bun.path_buffer_pool.put(key_buf);
        }
        const key = PathWatcherManager.makeKey(key_buf, resolved, recursive);
        _ = manager.mutex.lock();
        const gop = bun.handleOom(manager.watchers.getOrPut(bun.default_allocator, key));
        if (gop.found_existing) {
            const existing = gop.value_ptr.*;
            _ = bun.handleOom(existing.handlers.put(bun.default_allocator, ctx, .{}));
            _ = manager.mutex.unlock();
            return .{ .result = existing };
        }
        gop.key_ptr.* = bun.handleOom(bun.default_allocator.dupe(u8, key));
        const watcher = PathWatcher.@"new"(.{ .manager = manager, .path = bun.handleOom(bun.default_allocator.dupeZ(u8, resolved)), .recursive = recursive, .is_file = is_file });
        _ = bun.handleOom(watcher.handlers.put(bun.default_allocator, ctx, .{}));
        gop.value_ptr.* = watcher;
        if (comptime (!Environment.isMac)) {
            if (Platform.addWatch(manager, watcher).asErr()) |e| {
                _ = &e;
                _ = manager.unlinkWatcherLocked(watcher);
                _ = manager.mutex.unlock();
                watcher.manager = null;
                _ = watcher.destroy();
                return .{ .err = e.withoutPath() };
            }
            _ = manager.mutex.unlock();
            return .{ .result = watcher };
        }
        _ = manager.mutex.unlock();
        if (Platform.addWatch(manager, watcher).asErr()) |e| {
            _ = &e;
            _ = manager.mutex.lock();
            _ = manager.unlinkWatcherLocked(watcher);
            _ = watcher.handlers.swapRemove(ctx);
            if ((watcher.handlers.count() > 0)) {
                _ = watcher.emitError(e);
                _ = watcher.flush();
                _ = manager.mutex.unlock();
                return .{ .err = e.withoutPath() };
            }
            watcher.manager = null;
            _ = manager.mutex.unlock();
            _ = watcher.destroy();
            return .{ .err = e.withoutPath() };
        }
        return .{ .result = watcher };
}

pub fn walkSubtree(abs_dir: [:0]const u8, rel_dir: []const u8, comptime dirs_only: bool, ctx: anytype, comptime cb: *const fn (@TypeOf(ctx), [:0]const u8, []const u8, bool) void) void {
        var dfd: bun.FD = undefined;
        _ = &dfd;
        switch (bun.sys.open(abs_dir, ((bun.O.RDONLY | bun.O.DIRECTORY) | bun.O.CLOEXEC), 0)) {
.err => {
return;
},
.result => |f| {
dfd = f;
},
}
        defer {
        _ = dfd.close();
        }
        var it = bun.DirIterator.iterate(dfd, bun.DirIterator.PathType.u8);
        _ = &it;
        const abs_buf = bun.path_buffer_pool.get();
        defer {
        _ = bun.path_buffer_pool.put(abs_buf);
        }
        const rel_buf = bun.path_buffer_pool.get();
        defer {
        _ = bun.path_buffer_pool.put(rel_buf);
        }
        while (true) {
            switch (it.next()) {
.err => {
return;
},
.result => |opt| {
if (opt) |entry| {
                _ = &entry;
                const child_is_file = (entry.kind != .directory);
                if ((dirs_only and child_is_file)) {
                    continue;
                }
                const name = (if (@typeInfo(@TypeOf(entry)) == .@"enum" or @typeInfo(@TypeOf(entry)) == .@"union") @tagName(entry) else entry.name).slice();
                const child_abs = bun.path.joinZBuf(abs_buf, (&.{ abs_dir, name }), .posix);
                const child_rel: []const u8 = (if ((rel_dir.len == 0)) name else bun.path.joinStringBuf(rel_buf, (&.{ rel_dir, name }), .posix));
                _ = cb(ctx, child_abs, child_rel, child_is_file);
                if ((!child_is_file)) {
                    _ = walkSubtree(child_abs, child_rel, dirs_only, ctx, cb);
                }
            } else {
                return;
            }
},
}
        }
